From 427021468fd10b1ccbe72c7e8018ee088810f0a2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:46:24 +0100
Subject: [PATCH] applets/notes: ask before discarding a note from its context
 menu

Removing a note from its context menu skipped the "Discard this note?"
dialog that the trash button shows. Use the same check for the remove
action outside edit mode, and make the dialog open on the first try.

BUG: 453764
---
 applets/notes/qml/main.qml | 77 ++++++++++++++++++++++++--------------
 1 file changed, 48 insertions(+), 29 deletions(-)

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..ff1ddab40 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -117,6 +117,29 @@ PlasmoidItem {
         readonly property QtObject appletInterface: root

         property alias mainTextArea: mainTextArea
+
+        function removeNote() {
+            // No need to ask for confirmation in the cases when...
+            // ...the note is blank
+            if (mainTextArea.length === 0 ||
+                // ...the note's content is equal to the clipboard text
+
+                // Note that we are intentionally not using
+                // mainTextArea.getText() because it has a method of
+                // converting the text to plainText that does not produce
+                // the same exact output of various other methods, and if
+                // we go out of our way to match it, we will be
+                // depending on an implementation detail. So we instead
+                // roll our own version to ensure that the conversion
+                // is done in the same way every time.
+                documentHandler.stripAndSimplify(mainTextArea.text) === documentHandler.strippedClipboardText()
+            ) {
+                root.destroyAction.trigger();
+            } else {
+                discardConfirmationDialogLoader.open();
+            }
+        }
+
         // TODO figure out what element is missing in the requiredWidth calculation...
         Layout.minimumWidth: {
             if (root.inPanel && !root.compactInPanel) {
@@ -570,27 +593,7 @@ PlasmoidItem {
                     focusPolicy: Qt.TabFocus
                     icon.name: "edit-delete"
                     icon.color: root.textIconColor
-                    onClicked: {
-                        // No need to ask for confirmation in the cases when...
-                        // ...the note is blank
-                        if (mainTextArea.length === 0 ||
-                            // ...the note's content is equal to the clipboard text
-
-                            // Note that we are intentionally not using
-                            // mainTextArea.getText() because it has a method of
-                            // converting the text to plainText that does not produce
-                            // the same exact output of various other methods, and if
-                            // we go out of our way to match it, we will be
-                            // depending on an implementation detail. So we instead
-                            // roll our own version to ensure that the conversion
-                            // is done in the same way every time.
-                            documentHandler.stripAndSimplify(mainTextArea.text) === documentHandler.strippedClipboardText()
-                        ) {
-                            Plasmoid.internalAction("remove").trigger();
-                        } else {
-                            discardConfirmationDialogLoader.open();
-                        }
-                    }
+                    onClicked: backgroundItem.removeNote()
                     Accessible.name: removeTooltip.text
                     PlasmaComponents3.ToolTip {
                         id: removeTooltip
@@ -646,13 +649,8 @@ PlasmoidItem {
             id: discardConfirmationDialogLoader

             function open() {
-                const dialog = item as MessageDialog
-                if (dialog) {
-                    dialog.open();
-                } else {
-                    active = true;
-                }
-                dialog.visible = true;
+                active = true;
+                (item as MessageDialog).open();
             }

             active: false
@@ -666,7 +664,7 @@ PlasmoidItem {

                 onButtonClicked: (button, role) => {
                     if (button === MessageDialog.Discard) {
-                        Plasmoid.internalAction("remove").trigger()
+                        root.destroyAction.trigger()
                         visible = false;
                     }
                 }
@@ -678,6 +676,24 @@ PlasmoidItem {
         }
     }

+    // the applet's default "remove" action, which removes the widget right away
+    property QtObject destroyAction
+
+    PlasmaCore.Action {
+        id: removeAction
+        text: root.destroyAction?.text ?? ""
+        icon.name: "edit-delete"
+        // removing it in edit mode is deliberate, like for any other widget
+        onTriggered: {
+            const fullRepresentation = root.fullRepresentationItem as FullRepresentation;
+            if (Plasmoid.containment.corona.editMode || !fullRepresentation) {
+                root.destroyAction.trigger();
+            } else {
+                fullRepresentation.removeNote();
+            }
+        }
+    }
+
     PlasmaCore.ActionGroup {
         id: noteColorGroup
     }
@@ -721,6 +737,9 @@ PlasmoidItem {
     }

     Component.onCompleted: {
+        destroyAction = Plasmoid.internalAction("remove");
+        Plasmoid.setInternalAction("remove", removeAction);
+
         // Plasmoid configuration doesn't check before emitting change signal
         // explicit check is needed (at time of writing)
         if (note.id != Plasmoid.configuration.noteId) {
-- 
2.53.0

From 995924fdf26ae3c37e015448468312e3b7ea70f5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:46:23 +0100
Subject: [PATCH] Applet: connect the default remove action when creating it

The "remove" action was only connected to the removal at startup, to
whichever action was set at that point, so an applet couldn't replace it
with its own one. Connect the default action as soon as it is created.

CCBUG: 453764
---
 src/plasma/applet.cpp           | 1 -
 src/plasma/private/applet_p.cpp | 3 +++
 2 files changed, 3 insertions(+), 1 deletion(-)

diff --git a/src/plasma/applet.cpp b/src/plasma/applet.cpp
index dd2a9f667..ac4ea1f72 100644
--- a/src/plasma/applet.cpp
+++ b/src/plasma/applet.cpp
@@ -559,7 +559,6 @@ void Applet::flushPendingConstraintsEvents()
         if (closeApplet) {
             closeApplet->setEnabled(unlocked);
             closeApplet->setVisible(unlocked);
-            connect(closeApplet, SIGNAL(triggered(bool)), this, SLOT(askDestroy()), Qt::UniqueConnection);
         }

         QAction *configAction = d->actions.value(QStringLiteral("configure"));
diff --git a/src/plasma/private/applet_p.cpp b/src/plasma/private/applet_p.cpp
index 37297d115..53e072013 100644
--- a/src/plasma/private/applet_p.cpp
+++ b/src/plasma/private/applet_p.cpp
@@ -96,6 +96,9 @@ void AppletPrivate::init(const QVariantList &args)
     QAction *closeApplet = actions.value(QStringLiteral("remove"));
     if (closeApplet) {
         closeApplet->setText(i18nc("%1 is the name of the applet", "Remove %1", q->title()));
+        QObject::connect(closeApplet, &QAction::triggered, q, [this] {
+            askDestroy();
+        });
     }

     QAction *configAction = actions.value(QStringLiteral("configure"));
-- 
2.53.0
